function TypeLine({ text, active = true, instant = false, speed = 24 }) {
  const [n, setN] = useState(0);
  useEffect(() => {
    if (!active) { setN(0); return; }
    if (instant || (typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches)) { setN(text.length); return; }
    setN(0);
    let at = 0;
    const timer = setInterval(() => { at += 1; setN(at); if (at >= text.length) clearInterval(timer); }, speed);
    return () => clearInterval(timer);
  }, [text, active, instant, speed]);
  return <span aria-label={text}><span aria-hidden="true">{text.slice(0, n)}</span></span>;
}

function DecisionScene() {
  const [paused, setPaused] = useState(false);
  return <div className={`m4-scene ${paused ? 'paused' : ''}`}>
    <div className="m4-perspective" aria-hidden="true"><div className="m4-console">
      <div className="m4-console-floor"/><div className="m4-console-side"/>
      <div className="m4-console-screen"><span>{DATA.scene.label}</span><svg viewBox="0 0 150 66" fill="none"><path d="M10 33h35l17-21 27 42 18-21h33" stroke="currentColor" strokeWidth="3" strokeLinecap="round"/><circle cx="45" cy="33" r="5" fill="#eab873"/><circle cx="107" cy="33" r="5" fill="#eab873"/><path d="M10 60h130" stroke="currentColor" opacity=".25"/></svg><strong>{DATA.scene.ref}</strong></div>
    </div></div>
    <div className="m4-signals" aria-hidden="true"><span className="m4-tag">EVIDENCE → DECISION</span><div className="m4-signal-flow">{DATA.scene.stages.map((stage,index)=><div key={stage} style={{'--step':index}}><b>{String(index+1).padStart(2,'0')}</b><span>{stage}</span></div>)}</div><div className="m4-track"><i/></div><p>{DATA.scene.detail}</p></div>
    <button type="button" className="m4-motion" aria-pressed={paused} onClick={()=>setPaused(value=>!value)}>{paused?'Animatsiyani yoqish':'Animatsiyani to‘xtatish'}</button>
  </div>;
}

function EvidenceSlide({ slide, onReady }) {
  const [open,setOpen]=useState({});
  useEffect(()=>{if(Object.keys(open).length===3)onReady();},[open,onReady]);
  return <><p className="ml-sub">{slide.source}</p><div className="m4-evidence">{slide.items.map(([label,text],index)=><button type="button" key={label} className={`m4-evidence-card ${open[index]?'open':''}`} aria-expanded={!!open[index]} onClick={()=>setOpen(value=>({...value,[index]:true}))}><small>{label}</small><p>{open[index]?<TypeLine text={text}/>:'Dalilni ochish ↗'}</p></button>)}</div></>;
}

// Written answers keep IDs, numbers, negation, AM/PM and units meaningful.
function normalizeAnswer(value) { return String(value||'').trim().toLowerCase().replace(/[‘’]/g,"'").replace(/[.!?]+$/,'').replace(/(\D),|,(\D)/g,'$1$2').replace(/\s+/g,' '); }

function AssessmentSlide({ slide, onDone, attempt, final=false }) {
  const [index,setIndex]=useState(attempt.index||0);
  const [input,setInput]=useState(attempt.input||'');
  const [checked,setChecked]=useState(attempt.checked||null);
  const [complete,setComplete]=useState(attempt.complete||false);
  const [orders]=useState(()=>attempt.orders||(attempt.orders=slide.questions.map(q=>q.kind==='type'?[]:shuffled(q))));
  const history=useRef(attempt.history||(attempt.history={}));
  useEffect(()=>{Object.assign(attempt,{index,input,checked,complete});},[attempt,index,input,checked,complete]);
  const question=slide.questions[index];
  const written=question.kind==='type';
  const locked=!!checked&&(checked.correct||final);
  function grade(value) {
    if(locked)return;
    const correct=written?[question.answerText,...(question.accept||[])].some(answer=>normalizeAnswer(answer)===normalizeAnswer(value)):value===question.answer;
    const previous=history.current[index];
    history.current[index]={question:index+1,kind:question.kind,value,correct,firstTry:previous?previous.firstTry:correct,attempts:(previous?.attempts||0)+1,theoryRefs:question.theoryRefs};
    setChecked({value,correct});
  }
  function advance() {
    if(!checked||(!checked.correct&&!final))return;
    if(index+1<slide.questions.length){setIndex(index+1);setInput('');setChecked(null);return;}
    const answers=Object.values(history.current);
    setComplete(true);onDone({firstTry:answers.filter(answer=>answer.firstTry).length,total:slide.questions.length,answers});
  }
  if(complete)return <p className="ml-feedback good">{slide.questions.length} ta vazifa bajarildi. Birinchi urinish: {Object.values(history.current).filter(answer=>answer.firstTry).length} ta to‘g‘ri.</p>;
  return <><div className="m4-question-meta"><span className="ml-kick">{written?'YOZMA JAVOB':'QAROR'} · {index+1}/{slide.questions.length}</span>{final&&<span className="ml-note">O‘tish: {Math.ceil(slide.questions.length*DATA.threshold)}/{slide.questions.length} · birinchi urinish</span>}</div>
    {slide.kind==='mission'&&<DecisionScene/>}
    <p className="ml-lead m4-stem">{question.stem}</p>
    {written?<div className="m4-written"><label htmlFor={`answer-${index}`}>Javobingiz</label><input id={`answer-${index}`} autoComplete="off" spellCheck={false} value={input} disabled={locked} onChange={event=>{setInput(event.target.value);setChecked(null);}} onKeyDown={event=>{if(event.key==='Enter'&&input.trim())grade(input);}}/><button type="button" className="ml-button primary" disabled={locked||!input.trim()} onClick={()=>grade(input)}>Tekshirish →</button></div>:<div className="ml-options">{orders[index].map((option,position)=><button type="button" key={option.id} disabled={locked} className={`ml-option ${checked?.value===option.id?(checked.correct?'good':'bad'):''}`} onClick={()=>grade(option.id)}><i>{String.fromCharCode(65+position)}</i><span>{option.text}</span></button>)}</div>}
    {checked&&<p className={`ml-feedback ${checked.correct?'good':'bad'}`} role="status">{checked.correct?`✓ ${question.why}`:final?'Javob saqlandi. Keyingi savolga o‘ting.':written?question.hint:question.hints[checked.value]}</p>}
    <button type="button" className="ml-button primary" style={{justifySelf:'end'}} disabled={!checked||(!checked.correct&&!final)} onClick={advance}>{index+1<slide.questions.length?'Keyingi savol':'Natijani ko‘rish'} →</button>
  </>;
}

function HookSlide({ slide, onReady }) {
  useEffect(() => { onReady(); }, [onReady]);
  return <><DecisionScene/><div className="m4-hook"><span className="m4-tag">WORKPLACE CASE · O‘QUV VAZIYATI</span><p className="m4-hook-message">{slide.lines[0]}</p><p className="ml-lead">{slide.lines[1]}</p><p className="ml-sub">{slide.lines[2]}</p></div></>;
}

function DocumentSlide({ slide, onReady }) {
  const [active, setActive] = useState(0);
  const [reviewed, setReviewed] = useState({});
  const document = slide.documents[active];
  const complete = Object.keys(reviewed).length === slide.documents.length;
  useEffect(() => { if (complete) onReady(); }, [complete, onReady]);
  return <div className="m4-document-reader">
    <p className="ml-sub">{slide.instructions || "Manbani o‘qing. Har hujjatni tekshirgach belgilab chiqing; keyingi mashqlar shu detallarga asoslanadi."}</p>
    <div className="m4-tabs" role="group" aria-label="O‘quv hujjatlari">{slide.documents.map((item, index) => <button type="button" key={item.title} className={active === index ? "on" : ""} aria-pressed={active === index} onClick={() => setActive(index)}>{reviewed[index] ? "✓ " : ""}{item.title}</button>)}</div>
    <article className="m4-document" data-dense={document.rows.length > 4} key={active}><header><span className="m4-tag">SAMPLE DOCUMENT · {active + 1}/{slide.documents.length}</span><h2>{document.title}</h2></header><dl>{document.rows.map(([label, value]) => <div key={label}><dt>{label}</dt><dd>{value}</dd></div>)}</dl>{document.note && <p className="m4-document-note">{document.note}</p>}</article>
    <div className="ml-actions"><span className="ml-note" role="status">Ko‘rib chiqildi: {Object.keys(reviewed).length}/{slide.documents.length}</span><button type="button" className="ml-button primary" disabled={!!reviewed[active]} onClick={() => { setReviewed(prev => ({...prev,[active]:true})); if (active < slide.documents.length - 1) setActive(active + 1); }}>{reviewed[active] ? "Tekshirildi ✓" : "Hujjatni ko‘rib chiqdim →"}</button></div>
  </div>;
}

function DetailsSlide({ slide, onReady, onDone }) {
  const [values, setValues] = useState({});
  const [checked, setChecked] = useState(false);
  const [done, setDone] = useState(false);
  const [attempts, setAttempts] = useState(0);
  const normalize = normalizeAnswer;
  const correct = slide.fields.map(field => [field.answer, ...(field.accept || [])].some(answer => normalize(answer) === normalize(values[field.label])));
  function check(event) {
    event.preventDefault();
    if (done || slide.fields.some(field => !values[field.label]?.trim())) return;
    setChecked(true); setAttempts(value => value + 1);
    if (correct.every(Boolean)) { setDone(true); onDone?.({total:1,firstTry:attempts === 0 ? 1 : 0,attempts:attempts + 1}); onReady(); }
  }
  return <><div className="m4-source"><span className="m4-tag">MANBA · FACT CHECK</span><p>{slide.source}</p></div><div className="m4-details" role="group" aria-label="Ma’lumotlarni tekshirish" onKeyDown={event => { if (event.key === "Enter") check(event); }}>
    <div className="m4-fields">{slide.fields.map((field, index) => <label key={field.label}>{field.label}<input value={values[field.label] || ""} disabled={done} autoComplete="off" spellCheck={false} aria-invalid={checked && !correct[index]} aria-describedby={checked && !correct[index] ? `field-hint-${index}` : undefined} className={checked ? correct[index] ? "good" : "bad" : ""} onChange={event => { setChecked(false); setValues(prev => ({ ...prev, [field.label]: event.target.value })); }}/>{checked && !correct[index] && <small id={`field-hint-${index}`}>{field.hint || "Manbadagi shu detalni qayta tekshiring; raqam va vaqt birligini saqlang."}</small>}{checked && correct[index] && <small className="m4-correct">✓ Mos keldi</small>}</label>)}</div>
    {checked && <p role="status" className={`ml-feedback ${done ? "good" : "bad"}`}>{done ? "✓ Barcha detallar manbaga mos." : "Ayrim detallar mos emas. Tuzatib qayta tekshiring."}</p>}
    <button type="button" className="ml-button primary" onClick={check} disabled={done || slide.fields.some(field => !values[field.label]?.trim())}>Tekshirish →</button>
  </div></>;
}

function TheorySlide({ slide, index, onReady }) {
  const [phase, setPhase] = useState(0);
  const [run, setRun] = useState(0);
  const [skip, setSkip] = useState(false);
  const [flipped, setFlipped] = useState(false);
  const reduced = typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches;
  const visible = skip || reduced ? 8 : phase;
  useEffect(() => {
    if (skip || reduced) return;
    const timers = [];
    let delay = slide.explanation.length * 18 + 250;
    for (let step = 1; step <= 3; step++) { timers.push(setTimeout(() => setPhase(step), delay)); delay += 470; }
    for (let point = 0; point < 2; point++) { timers.push(setTimeout(() => setPhase(point + 4), delay)); delay += slide.points[point].length * 14 + 180; }
    timers.push(setTimeout(() => setPhase(6), delay)); delay += slide.example.length * 18 + 200;
    timers.push(setTimeout(() => setPhase(7), delay)); delay += slide.translation.length * 18 + 220;
    timers.push(setTimeout(() => setPhase(8), delay));
    return () => timers.forEach(clearTimeout);
  }, [slide, run, skip, reduced]);
  const show = at => visible >= at ? "ml-theory-enter" : "ml-theory-hidden";
  return <div className="ml-theory">
    <div className="ml-theory-top"><span className="ml-kick">ASOSIY QOIDA · {index + 1}/{DATA.theoryCount}</span><div className="ml-theory-controls"><button type="button" onClick={() => { setPhase(0); setSkip(false); setFlipped(false); setRun(value => value + 1); }}>Qayta</button><button type="button" disabled={visible === 8} onClick={() => setSkip(true)}>Hammasi</button></div></div>
    <p className="ml-theory-rule"><TypeLine key={`rule-${run}`} text={slide.explanation} instant={skip} speed={18} /></p>
    <div className="ml-theory-flow" aria-label={visible >= 3 ? slide.steps.map(step => step[1]).join(" → ") : undefined}>{slide.steps.map(([label, value], at) => <React.Fragment key={at}>{at > 0 && <span className={`ml-theory-arrow ${show(at + 1)}`} aria-hidden={visible < at + 1}>→</span>}<div className={`ml-theory-step ${show(at + 1)}`} aria-hidden={visible < at + 1}><small>{label}</small><strong>{value}</strong></div></React.Fragment>)}</div>
    <div className="ml-theory-points">{slide.points.map((point, at) => <p key={at} className={show(at + 4)} aria-hidden={visible < at + 4}><TypeLine key={`point-${run}-${at}`} text={point} active={visible >= at + 4} instant={skip} speed={14} /></p>)}</div>
    <div className={`ml-theory-example ${show(6)}`} aria-hidden={visible < 6}><strong><TypeLine key={`example-${run}`} text={slide.example} active={visible >= 6} instant={skip} speed={18} /></strong><span><TypeLine key={`translation-${run}`} text={slide.translation} active={visible >= 7} instant={skip} speed={18} /></span></div>
    <button type="button" className={`ml-theory-flip ${show(8)} ${flipped ? "on" : ""}`} disabled={visible < 8} aria-hidden={visible < 8} aria-pressed={flipped} onClick={() => { setFlipped(true); onReady(); }}><span className="ml-theory-flip-inner"><span className="ml-theory-face"><small>XATO · TUZATISH UCHUN BOSING</small><strong>{slide.wrong}</strong></span><span className="ml-theory-face back"><small>TO‘G‘RI ✓</small><strong>{slide.right}</strong><em>{slide.why}</em></span></span></button>
  </div>;
}

function Card({ text, index, opened, onOpen }) {
  const divider = text.indexOf(":");
  const label = divider > 0 && divider < 42 ? text.slice(0, divider + 1) : "";
  const rest = label ? text.slice(divider + 1).trim() : text;
  return <button type="button" className={`ml-card reveal ${opened ? "open" : ""}`} style={{ "--delay": `${index * .11}s` }} aria-expanded={opened} onClick={onOpen}><div className="hint">{label || `QOIDA ${index + 1}`}</div><p className="hidden-copy">{opened ? <TypeLine text={rest} /> : "Ko‘rish uchun bosing ↗"}</p></button>;
}

function RevealSlide({ slide, onReady }) {
  const [seen, setSeen] = useState({});
  const cards = slide.cards || [];
  useEffect(() => { if (cards.length === 0 || Object.keys(seen).length >= cards.length) onReady(); }, [seen, cards.length, onReady]);
  return <><div className="ml-card-grid"><div className="ml-card"><div className="hint">NAZARIYA · {slide.number}</div><p className="ml-lead">{slide.heading}</p><small>Kartalarni ketma-ket ochib qoidani o‘rganing.</small></div>{cards.map((line, index) => <Card key={index} text={line} index={index} opened={!!seen[index]} onOpen={() => setSeen(prev => ({ ...prev, [index]: true }))} />)}</div></>;
}

function ChatSlide({ slide, onReady }) {
  const [translation, setTranslation] = useState(false);
  useEffect(() => { const timer = setTimeout(onReady, Math.min(1800, (slide.chat?.length || 1) * 200)); return () => clearTimeout(timer); }, [onReady, slide]);
  return <><div className="ml-chat">{slide.chat.map(([who, line], index) => <div className={`ml-bubble ${index % 2 ? "right" : ""}`} style={{ "--delay": `${index * .14}s` }} key={index}><small>{who}</small><p>{line}</p></div>)}</div>{slide.translation && <><button type="button" className="ml-button" style={{ justifySelf: "start" }} onClick={() => setTranslation(!translation)} aria-expanded={translation}>Tarjima {translation ? "−" : "+"}</button>{translation && <p className="ml-sub">{slide.translation}</p>}</>}</>;
}

function VocabSlide({ slide, onReady }) {
  const [seen, setSeen] = useState({});
  useEffect(() => { if (Object.keys(seen).length >= slide.rows.length) onReady(); }, [seen, slide.rows.length, onReady]);
  return <><p className="ml-sub">Kartalarni bosing: so‘zning ma’nosi va logistikadagi misolini ko‘ring.</p><div className="ml-card-grid cols3">{slide.rows.map(([word, meaning, example], index) => <button key={word} type="button" className={`ml-vocab-card ${seen[index] ? "open" : ""}`} style={{ animationDelay: `${index * .08}s` }} onClick={() => setSeen(prev => ({ ...prev, [index]: true }))} aria-label={`${word}: ${meaning}`} aria-pressed={!!seen[index]}><span className="ml-vocab-inner"><span className="ml-vocab-face"><small className="hint">LOGISTICS · {index + 1}</small><strong>{word}</strong><small>Bosing ↗</small></span><span className="ml-vocab-face back"><strong>{meaning}</strong><small>{example}</small></span></span></button>)}</div></>;
}

function shuffled(question) {
  const items = question.options.map((text, id) => ({ text, id }));
  for (let i = items.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [items[i], items[j]] = [items[j], items[i]];
  }
  return items;
}

function BuildSlide({ slide, onDone }) {
  const [index, setIndex] = useState(0);
  const [selected, setSelected] = useState([]);
  const [checked, setChecked] = useState(false);
  const [first, setFirst] = useState(0);
  const [attempted, setAttempted] = useState({});
  const [completed, setCompleted] = useState(false);
  const [tokenOrders] = useState(() => slide.builds.map(item => shuffled({ options: item.parts })));
  const build = slide.builds[index];
  const normalize = value => value.replace(/,/g, "").replace(/\s+([?.!])/g, "$1").replace(/[?.!]$/, "").replace(/\s+/g, " ").trim().toLowerCase();
  const assembled = selected.map(i => build.parts[i]).join(" ");
  const isRight = normalize(assembled) === normalize(build.answer);
  const check = () => {
    setChecked(true);
    if (!attempted[index]) { setAttempted(prev => ({ ...prev, [index]: true })); if (isRight) setFirst(prev => prev + 1); }
  };
  const advance = () => {
    if (index + 1 < slide.builds.length) { setIndex(index + 1); setSelected([]); setChecked(false); return; }
    setCompleted(true); onDone({ firstTry: first, total: slide.builds.length });
  };
  if (completed) return <p className="ml-feedback good">3 ta gap tuzildi. Birinchi urinishda {first} ta to‘g‘ri.</p>;
  return <><span className="ml-kick">GAP {index + 1} / {slide.builds.length}</span><p className="ml-sub">So‘zlarni to‘g‘ri tartibda birlashtiring.</p><div className="ml-token-wrap">{selected.length ? selected.map((partIndex, at) => <button type="button" key={`${partIndex}-${at}`} className="ml-token" onClick={() => { setSelected(prev => prev.filter((_, i) => i !== at)); setChecked(false); }}>{build.parts[partIndex]}</button>) : <span className="ml-dim">Gap shu yerda yig‘iladi...</span>}</div><div className="ml-token-wrap">{tokenOrders[index].map(({ text: part, id: partIndex }) => <button type="button" key={partIndex} className="ml-token" disabled={selected.includes(partIndex)} onClick={() => { setSelected(prev => [...prev, partIndex]); setChecked(false); }}>{part}</button>)}</div>{checked && <p className={`ml-feedback ${isRight ? "good" : "bad"}`} aria-live="polite">{isRight ? "✓ To‘g‘ri gap tuzildi." : "So‘z tartibini qayta ko‘ring. Fe’lning joyiga e’tibor bering."}</p>}<div className="ml-actions"><button type="button" className="ml-button" onClick={() => { setSelected([]); setChecked(false); }}>Qayta boshlash</button>{checked && isRight ? <button type="button" className="ml-button primary" onClick={advance}>Keyingi gap →</button> : <button type="button" className="ml-button primary" disabled={selected.length !== build.parts.length} onClick={check}>Tekshirish →</button>}</div></>;
}

function SummarySlide({ slide, rate, setRate }) {
  return <><p className="ml-sub">Iboralarni ovoz chiqarib o‘qing va o‘zingizni baholang. Ovoz yozilmaydi.</p><div className="ml-summary-grid">{slide.phrases.map((phrase, index) => <div className="ml-phrase" key={index} style={{ "--delay": `${index * .1}s` }}><p>{phrase}</p><div className="ml-rate">{[["hard", "Qiyin"], ["ok", "O‘rtacha"], ["easy", "Oson"]].map(([value, label]) => <button type="button" key={value} className={rate[index] === value ? "on" : ""} onClick={() => setRate(prev => ({ ...prev, [index]: value }))}>{label}</button>)}</div></div>)}</div>{slide.extras.map((extra, index) => <p className="ml-sub" key={index}>{extra}</p>)}</>;
}

function Result({ result }) {
  const passed = result.firstTry / result.total >= DATA.threshold;
  return <div className="ml-result"><div className="ml-result-art">{passed && <div className="ml-confetti" aria-hidden="true">{Array.from({ length: 16 }, (_, index) => <i key={index} style={{ "--angle": `${index * 22.5}deg`, "--delay": `${index * -.22}s` }} />)}</div>}<div className="ml-ring" style={{ "--score": `${result.firstTry / result.total * 100}%` }} role="img" aria-label={`${result.firstTry} / ${result.total}`}><span><small>NATIJA</small><strong>{result.firstTry}/{result.total}</strong></span></div></div><div className="ml-result-copy"><svg viewBox="0 0 72 64" fill="none" aria-hidden="true"><path d="M5 9c12-4 23-3 31 4 8-7 19-8 31-4v44c-12-4-23-3-31 4-8-7-19-8-31-4V9Z" fill="currentColor" opacity=".8"/><path d="M36 13v44" stroke="#30251a" strokeWidth="3"/><circle cx="57" cy="11" r="11" fill="#e8c98f"/><path d="m52 11 3 3 6-7" stroke="#20252a" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/></svg><h2>{passed ? "Nazariy dars yakunlandi" : "Nazariyani takrorlang"}</h2><p>{passed ? DATA.code === "M4L08" ? "Yakuniy modul nazariyasi tugadi. Fakt, cheklov va dalil asosida professional muloqotni mashq qildingiz." : "Tabriklaymiz! Endi bilimni amaliy mashg‘ulotda mustahkamlang." : `O‘tish uchun kamida ${Math.ceil(result.total * DATA.threshold)} ta to‘g‘ri javob kerak. Qoidalarni qayta ko‘rib, tezkor testni takrorlang.`}</p><b className="ml-strong">{passed ? "Ajoyib, o‘tdingiz!" : "Yana urinib ko‘ring"}</b></div></div>;
}

export default function Lesson({ onFinished, onProgress }) {
  const [current, setCurrent] = useState(0);
  const [ready, setReady] = useState({});
  const [results, setResults] = useState({});
  const attempts = useRef({});
  const [rate, setRate] = useState({});
  const [finished, setFinished] = useState(false);
  const started = useRef(Date.now());
  const done = useRef(false);
  const slides = DATA.slides;
  const slide = slides[current];
  const bodyRef = useRef(null);
  useEffect(() => { if(bodyRef.current) bodyRef.current.scrollTop = 0; }, [current]);
  const rapidIndex = slides.findIndex(item => item.final);
  const rapid = results[rapidIndex];
  const resultScreen = current === rapidIndex && !!rapid;
  useEffect(() => { onProgress?.({ current: current + 1, total: slides.length }); }, [current, onProgress, slides.length]);
  const markReady = useCallback(() => setReady(prev => prev[current] ? prev : ({ ...prev, [current]: true })), [current]);
  const record = value => { setResults(prev => ({ ...prev, [current]: value })); markReady(); };
  const finish = () => {
    if (done.current || !rapid || rapid.firstTry / rapid.total < DATA.threshold) return;
    done.current = true; setFinished(true);
    const score = rapid || { firstTry: 0, total: DATA.code === "M4L08" ? 12 : 6 };
    const all = Object.values(results);
    onFinished?.({ lessonId: `${DATA.code}-learn`, lessonTitle: DATA.title, durationSec: Math.max(0, Math.round((Date.now() - started.current) / 1000)), totalQuestions: score.total, correctAnswers: score.firstTry, scorePercent: Math.round(score.firstTry / score.total * 100), passed: score.firstTry / score.total >= DATA.threshold, firstTryStats: { total: all.reduce((sum, item) => sum + item.total, 0), firstTryCorrect: all.reduce((sum, item) => sum + item.firstTry, 0) }, skillTags: DATA.skillTags, answers: Object.entries(results).map(([index, value]) => ({ slide: Number(index) + 1, ...value })), profile: { aloud: rate } });
  };
  let content;
  const props = { slide, onReady: markReady, onDone: record };
  if (slide.kind === "hook") content = <HookSlide key={current} {...props} />;
  else if (slide.kind === "document") content = <DocumentSlide key={current} {...props} />;
  else if (slide.kind === "evidence") content = <EvidenceSlide key={current} {...props} />;
  else if (slide.kind === "details") content = <DetailsSlide key={current} {...props} />;
  else if (slide.kind === "theory") content = <TheorySlide key={current} {...props} index={current - 1} />;
  else if (slide.kind === "read") content = <ChatSlide key={current} {...props} />;
  else if (slide.kind === "vocab") content = <VocabSlide key={current} {...props} />;
  else if (slide.kind === "mission" || slide.kind === "quiz") content = resultScreen ? <Result result={rapid} /> : <AssessmentSlide key={current} {...props} attempt={attempts.current[current] || (attempts.current[current] = {})} final={current === rapidIndex} />;
  else if (slide.kind === "build") content = <BuildSlide key={current} {...props} />;
  else if (slide.kind === "summary") content = <SummarySlide key={current} {...props} rate={rate} setRate={setRate} />;
  else content = <RevealSlide key={current} {...props} />;
  const failedTest = resultScreen && rapid.firstTry / rapid.total < DATA.threshold;
  const canContinue = !failedTest && (!!ready[current] || slide.kind === "summary");
  return <main className="ml-root"><style>{CSS + MODULE_CSS}</style><header className="ml-head"><span className="ml-eyebrow">M04 / OPERATIONS · {DATA.code} · {current + 1}/{slides.length}</span><span className="ml-progress" aria-hidden="true">{slides.map((_, index) => <i key={index} className={index <= current ? "on" : ""} />)}</span></header><section className="ml-body" ref={bodyRef}><div className="ml-slide" data-kind={slide.kind} key={current}><div><h1 className="ml-title"><TypeLine text={slide.heading} /></h1></div>{current === 0 && <p className="ml-sub">{DATA.goal}</p>}{content}</div></section><footer className="ml-foot"><button type="button" className="ml-button" disabled={current === 0} onClick={() => setCurrent(current - 1)}>← Orqaga</button>{!canContinue && <span className="ml-note">Davom etish uchun vazifani bajaring</span>}{failedTest && <button type="button" className="ml-button primary" onClick={() => { delete attempts.current[current]; setResults(prev => { const next = { ...prev }; delete next[current]; return next; }); setReady(prev => ({ ...prev, [current]: false })); }}>Testni qayta ishlash →</button>}{finished ? <span className="ml-feedback good">Natija saqlandi ✓</span> : current < slides.length - 1 ? <button type="button" className="ml-button primary" disabled={!canContinue} onClick={() => setCurrent(current + 1)}>{resultScreen ? "Davom etish" : "Keyingi slayd"} →</button> : <button type="button" className="ml-button primary" onClick={finish}>Darsni yakunlash →</button>}</footer></main>;
}
